SELECT n.notice_no, n.notice_category, n.notice_title, n.notice_hit, n.notice_file_cnt, n.notice_created FROM tb_notice n WHERE n.notice_visible_yn = 'Y'
AND n.notice_category = #{noticeCategory}
AND n.notice_title LIKE CONCAT('%', #{searchName}, '%')
AND n.notice_content_text LIKE CONCAT('%', #{searchName}, '%')
ORDER BY n.notice_created desc LIMIT #{pageSize} OFFSET #{startRowNum}

SELECT n.notice_no, n.notice_category, n.notice_title, n.notice_hit, n.notice_file_cnt, n.notice_pin_yn, n.notice_visible_yn, n.notice_created FROM tb_notice n
AND n.notice_category = #{noticeCategory}
AND n.notice_title LIKE CONCAT('%', #{searchName}, '%')
AND n.notice_content_text LIKE CONCAT('%', #{searchName}, '%')
ORDER BY n.notice_created desc LIMIT #{pageSize} OFFSET #{startRowNum}
